package env

import "os"

// AppEnv - значение переменной окружения APP_ENV, прочитанное один раз при
// загрузке пакета.
var AppEnv string

// init паникует ещё до входа в main(), если обязательная переменная
// окружения не задана - так ошибка конфигурации видна сразу при старте,
// а не где-то посреди работы программы.
func init() {
	AppEnv = os.Getenv("APP_ENV")
	if AppEnv == "" {
		panic("env: переменная окружения APP_ENV не задана, укажи её перед запуском")
	}
}
